"""Dev helper: writes starter_site.json (first-install pages, menu, footer, short addresses, ticker) and page_presets.json."""
import json, os
APP = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'pcpb_website')

def B(t, shade=0, **v):
    return {'web_template': 'PCPB ' + t, 'values': v, 'shade': shade}

def head(title, text):
    return B('Page Header', title=title, text=text, show_crumbs=1)
ABOUT = '<p>The Pest Control Products Board (PCPB) is a statutory body established under the Pest Control Products Act, Cap 346 of the Laws of Kenya. The Board regulates the manufacture, import, export, distribution, sale, use and disposal of pest control products.</p>\n<h3>Vision</h3><p>To be a world class regulatory agency for pest control products.</p>\n<h3>Mission</h3><p>To regulate pest control products so that they are safe, effective and of good quality, protecting human health, animals and the environment.</p>\n<h3>Core values</h3><ul><li>Customer focus</li><li>Professionalism</li><li>Integrity</li><li>Confidentiality</li><li>Equity and equality</li><li>Teamwork</li><li>Innovation</li></ul>'
pages = [{'route': 'site', 'title': 'Home', 'description': 'The Pest Control Products Board regulates pest control products in Kenya. Search registered products and licensed premises, and apply for services online.', 'blocks': [B('Hero', eyebrow='Statutory regulator of pest control products', title="Safe, effective pest control products for Kenya's farms, homes and environment", text='The Pest Control Products Board regulates the manufacture, import, distribution, use and disposal of pest control products under the Pest Control Products Act, Cap. 346.', button_1_label='Browse the registers', button_1_url='/registers', button_2_label='Apply for a service', button_2_url='/online-services', show_check=1, check_title='Product status check', check_text='Search a product name, active ingredient or registration number across every public register.', check_placeholder='Product, ingredient or registration no.', check_chips=''), B('Cards', title='What would you like to do?', columns='3', cards=[{'icon': 'form', 'title': 'Apply for a service', 'text': 'Start an application on the PCPB portal.', 'url': '/online-services'}, {'icon': 'leaf', 'title': 'Search registered products', 'text': 'Check that a product is approved for use in Kenya.', 'url': '/registers'}, {'icon': 'building', 'title': 'Find licensed premises', 'text': 'Premises inspected and licensed by PCPB.', 'url': '/registers'}, {'icon': 'megaphone', 'title': 'Latest notices', 'text': 'Notices, circulars and safety alerts.', 'url': '/news'}, {'icon': 'gavel', 'title': 'Tenders', 'text': 'Open and past tenders of the Board.', 'url': '/tenders'}, {'icon': 'download', 'title': 'Forms and guidelines', 'text': 'Application forms, guidelines and the service charter.', 'url': '/downloads'}]), B('Registers Strip', shade=1, title='Registers at a glance'), B('Services', title='Featured services', view_all_label='All services', view_all_url='/online-services', mode='Featured', limit=6), B('News', shade=1, title='Latest updates', view_all_label='All news and notices', view_all_url='/news', types='All', limit=3, layout='Cards'), B('Tenders', title='Open tenders', view_all_label='All tenders', view_all_url='/tenders', group='Open', limit=3), B('Call to Action', title='Seen a suspect or illegal product?', text='Report unregistered, counterfeit or wrongly labelled pest control products to the Board.', button_label='Contact the Board', button_url='/contact-us', style='Green')]}, {'route': 'about-us', 'title': 'About us', 'blocks': [head('About the Board', 'Who we are, our mandate and our commitments.'), B('Text', content=ABOUT), B('Leadership', shade=1, title='Leadership', groups='All', feature_first=0)]}, {'route': 'leadership', 'title': 'Leadership', 'blocks': [head('Leadership', 'The Board and the management of the Pest Control Products Board.'), B('Leadership', title='Board Chairperson', groups='Board Chairperson', feature_first=1), B('Leadership', title='Chief Executive Officer', groups='Chief Executive Officer', feature_first=1), B('Leadership', shade=1, title='Board members', groups='Board Member'), B('Leadership', title='Executive management', groups='Executive Management')]}, {'route': 'online-services', 'title': 'Services', 'blocks': [head('Online services', 'Applications are made on the PCPB portal. Sign in or create an account to apply.'), B('Services', mode='All', group_by=1)]}, {'route': 'registers', 'title': 'Registers', 'blocks': [head('Public registers', "Every list here is read live from the Board's records."), B('Register Search', shade=1, title='Search every register', subtitle='By product name, active ingredient, registration number or premises.', placeholder='Search the registers'), B('Register Index', show_counts=1, columns='3')]}, {'route': 'news', 'title': 'News and notices', 'blocks': [head('News and notices', 'News, public notices, circulars and safety alerts from the Board.'), B('News', types='All', limit=30, layout='List'), B('News', shade=1, title='Archive', types='All', limit=50, layout='List', archive=1)]}, {'route': 'tenders', 'title': 'Tenders', 'blocks': [head('Tenders', 'Current and past tenders of the Pest Control Products Board.'), B('Tenders', title='Open tenders', group='Open', limit=50), B('Tenders', shade=1, title='Closed and awarded', group='Archive', limit=50)]}, {'route': 'careers', 'title': 'Careers', 'blocks': [head('Careers', 'Open vacancies at the Board. Vacancies are published by Human Resources and appear here by themselves.'), B('Jobs', limit=50)]}, {'route': 'downloads', 'title': 'Downloads', 'blocks': [head('Downloads', 'Forms, guidelines, regulations, reports and other documents.'), B('Downloads', category='All', limit=200, group_by=1)]}, {'route': 'gallery', 'title': 'Gallery', 'blocks': [head('Gallery', "Pictures from the Board's work across the country."), B('Gallery')]}, {'route': 'contact-us', 'title': 'Contact and location', 'blocks': [head('Contact and location', 'Reach the head office or the regional office nearest to you.'), B('Contact and Map', show_map=1, show_offices=1, button_label='Send us a message', button_url='/contact')]}]
