footer = [('The Board', '', ''), ('About us', '/about-us', 'The Board'), ('Leadership', '/leadership', 'The Board'), ('Careers', '/careers', 'The Board'), ('Tenders', '/tenders', 'The Board'), ('Contact and location', '/contact-us', 'The Board'), ('Find', '', ''), ('Registers', '/registers', 'Find'), ('Online services', '/online-services', 'Find'), ('News and notices', '/news', 'Find'), ('Downloads', '/downloads', 'Find'), ('Gallery', '/gallery', 'Find')]
redirects = [('about', '/about-us'), ('jobs', '/careers'), ('vacancies', '/careers'), ('products', '/registers/registered-products'), ('premises', '/registers/licensed-premises'), ('documents', '/downloads'), ('resources', '/downloads'), ('contact-us/form', '/contact')]
ticker = [('Check first', 'Search every register by product, active ingredient or registration number', '/registers'), ('Safety', 'Always read and follow the label before using a pest control product', '')]
json.dump({'pages': pages, 'menu': menu, 'footer': footer, 'redirects': redirects, 'ticker': ticker}, open(APP + '/starter_site.json', 'w'), indent=1)
presets = {'blank': {'label': 'Empty page', 'description': 'Start with nothing and add sections.', 'blocks': []}, 'standard': {'label': 'Text page', 'description': 'A title band and a text section. Good for policies and information pages.', 'blocks': [B('Page Header', title='{{title}}', show_crumbs=1), B('Text', content='<p>Write your text here.</p>')]}, 'landing': {'label': 'Landing page', 'description': 'Banner, cards, text with picture and a call to action.', 'blocks': [B('Hero', title='{{title}}', text='A short introduction.', show_check=0), B('Cards', title='Highlights', columns='3', cards=[{'icon': 'leaf', 'title': 'First card', 'text': 'Text'}, {'icon': 'shield', 'title': 'Second card', 'text': 'Text'}, {'icon': 'doc', 'title': 'Third card', 'text': 'Text'}]), B('Image and Text', title='A heading', content='<p>Text beside a picture.</p>'), B('Call to Action', title='A closing message', button_label='Contact us', button_url='/contact-us')]}, 'list': {'label': 'Documents page', 'description': 'A title band and a list of documents from one category.', 'blocks': [B('Page Header', title='{{title}}', show_crumbs=1), B('Downloads', category='All', limit=100, group_by=0)]}, 'form': {'label': 'Form page', 'description': 'A title band and a web form. What visitors submit goes into the ERP.', 'blocks': [B('Page Header', title='{{title}}', show_crumbs=1), B('Form', display='On the page')]}}
json.dump(presets, open(APP + '/page_presets.json', 'w'), indent=1)
print('ok')
